// === main.js（主进程） ===
const { app, BrowserWindow, ipcMain, dialog } = require('electron');
const path = require('path');
const fs = require('fs');

let mainWindow;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,  // 必须：隔离 preload 与页面上下文
      nodeIntegration: false,   // 必须：渲染进程不能用 Node
      sandbox: true             // Electron 20+ 默认，preload 也受限
    }
  });
  mainWindow.loadFile('index.html');
}

app.whenReady().then(createWindow);

// invoke/handle：请求-响应，渲染进程 await 拿结果
ipcMain.handle('open-file', async () => {
  const result = await dialog.showOpenDialog({ properties: ['openFile'] });
  // canceled 时 filePaths 为空数组，返回 null 让渲染进程知道用户取消了
  return result.canceled ? null : result.filePaths[0];
});

// send/on：单向通知，主进程执行后主动回复
ipcMain.on('save-data', (event, data) => {
  // 参数校验：渲染进程是不可信的
  if (!data || typeof data !== 'object') {
    event.reply('save-error', 'Invalid data');
    return;
  }
  fs.writeFileSync('data.json', JSON.stringify(data));
  event.reply('save-success');
});

// === preload.js（安全桥接层） ===
const { contextBridge, ipcRenderer } = require('electron');

// 只暴露白名单 API，不暴露整个 ipcRenderer
contextBridge.exposeInMainWorld('electronAPI', {
  openFile: () => ipcRenderer.invoke('open-file'),
  saveData: (data) => ipcRenderer.send('save-data', data),
  onSaveSuccess: (callback) => {
    // 包装 listener 避免页面直接拿到原始 ipcRenderer.on
    const listener = (_event, ...args) => callback(...args);
    ipcRenderer.on('save-success', listener);
    // 返回清理函数
    return () => ipcRenderer.removeListener('save-success', listener);
  }
});

// === renderer.js（渲染进程） ===
// window.electronAPI 由 contextBridge 注入，类型安全、上下文隔离
async function handleOpenFile() {
  const filePath = await window.electronAPI.openFile();
  if (filePath === null) {
    console.log('用户取消了选择');
    return;
  }
  console.log('选择的文件:', filePath);
}

function handleSave() {
  window.electronAPI.saveData({ key: 'value' });
  const cleanup = window.electronAPI.onSaveSuccess(() => {
    console.log('保存成功');
    cleanup(); // 用完移除，避免内存泄漏
  });
}
